# Block accessors
def VOLTAGE(v): return VOLTAGE_BASE + v * VOLTAGE_STRIDE
def CURRENT(c): return CURRENT_BASE + c * CURRENT_STRIDE
def NT_AIN(k): return NT_AIN_BASE + k * NT_AIN_STRIDE
def TOTALS(k): return TOTALS_BASE + k * TOTALS_STRIDE
def CAL_V(v): return CAL_V_BASE + v * CAL_V_STRIDE
def CAL_I(c): return CAL_I_BASE + c * CAL_I_STRIDE
def CHMAP_ASSOC(c): return CHMAP_ASSOC_BASE + c * CHMAP_ASSOC_STRIDE
def CHMAP_MODEL(c): return CHMAP_MODEL_BASE + c * CHMAP_MODEL_STRIDE
def LATCH(b): return LATCH_BASE + b * LATCH_STRIDE
def LATCH_CHE(c): return LATCH_CHE_BASE + c * LATCH_CHE_STRIDE
def ENERGY(e): return ENERGY_BASE + e * ENERGY_STRIDE
def GROUP_ENERGY(g): return GROUP_ENERGY_BASE + g * GROUP_ENERGY_STRIDE
def GROUP_ENERGY_MWH(g): return GROUP_ENERGY_MWH_BASE + g * GROUP_ENERGY_MWH_STRIDE
def GROUP_ENERGY_UWH(g): return GROUP_ENERGY_UWH_BASE + g * GROUP_ENERGY_UWH_STRIDE
def HIST_REC(r): return HIST_REC_BASE + r * HIST_REC_STRIDE
def EVENT_REC(r): return EVENT_REC_BASE + r * EVENT_REC_STRIDE
def METER_GROUP(g): return METER_GROUP_BASE + g * METER_GROUP_STRIDE

